commit;

select * from my_table;

var b  varchar2(1000)
begin
  :b := 'Daniel, Alice, Drop Table, other junk, Fran';
end;
/

select :b from dual;

:B

Daniel, Alice, Drop Table, other junk, Fran

with temp as
      ( select :b  s  from dual
      ),
   w_list as
      ( select level ,
               trim(regexp_substr(t.s, '[^,]+', 1, level))  fs
          from temp  t
        connect by level <= length ( regexp_replace(t.s, '[^,]+')) + 1
      )
select *
from my_table mt
where mt.col_val in ( select fs from w_list )
/

        ID COL_VAL
- -
       523 Daniel
       123 Alice
       993 Fran

3 rows selected.

